	if changed, err := s.SetAttachmentAccess("dev-1", "att-1", "dev-2", true); err != nil || !changed {
		t.Fatalf("grant = %v %v", changed, err)
	}
	if err := s.Close(); err != nil {
		t.Fatal(err)
	}

